// ══════════════════════════════════════════════════════════════════
//  CONFIGURE HERE -- change these 4 variables, nothing else
// ══════════════════════════════════════════════════════════════════

// Where to save scraped articles (can be a different repo!)
const OUTPUT_DIR = 'C:\\Users\\Voelt\\ai-dev-starter\\data\\knowledge\\raw\\medium';

// What to scrape -- MODE + SOURCE
//   'list'      + list URL (DEFAULT)
//   'tag'       + tag name (no cookies needed)
//   'article'   + article URL
//   'feed'      + RSS feed URL
//   'bookmarks' + (SOURCE ignored)
const MODE   = 'list';
const SOURCE = 'https://medium.com/@voeltzke.christoph/list/coding-6c7978acb372';
const MAX    = 20;

// ══════════════════════════════════════════════════════════════════
//  Build command (don't edit below)
// ══════════════════════════════════════════════════════════════════
let args;
switch (MODE) {
  case 'list':      args = `--list "${SOURCE}" --max ${MAX}`; break;
  case 'article':   args = `--article "${SOURCE}" --max ${MAX}`; break;
  case 'feed':      args = `--url "${SOURCE}" --max ${MAX}`; break;
  case 'bookmarks': args = `--bookmarks --max ${MAX}`; break;
  default:          args = `--tag "${SOURCE}" --max ${MAX}`; break;
}

args += ` --output "${OUTPUT_DIR}"`;

const scrapeCmd = `cd /d C:\\Users\\Voelt\\ai-dev-starter && .venv\\Scripts\\python.exe -m knowledge.medium_scraper ${args}`;

return [{ json: { scrapeCmd, outputDir: OUTPUT_DIR, source: MODE === 'bookmarks' ? 'bookmarks' : SOURCE } }];
